/*!
 * wega-music-lap4.js - Lap 4 add-on for the Wega's Challenge music pack.
 * Load AFTER wega-music.js and BEFORE the game module. It registers a "lap4" track with
 * WegaMusic so WegaMusic.init() decodes it with the others and WegaMusic.play("lap4") works.
 * Track: "DIVE" OST - the song that plays at the last lap - supplied by the player.
 */
(function (global) {
  "use strict";
  var D = global.WEGA_MUSIC_DATA, W = global.WegaMusic;
  if (!D || !W) { if (global.console) console.warn("[wega-music-lap4] load wega-music.js first"); return; }
  D.lap4 = {
    title: "DIVE (Last Lap Theme)",
    credit: "DIVE OST - the song that plays at the last lap",
    duration: 122.776,
    loopStart: 0.05,
    loopEnd: 121.32,
    gain: 1.1,
    src: "data:audio/mpeg;base64,"
  };
  if (W.tracks.indexOf("lap4") < 0) W.tracks.push("lap4");
})(typeof window !== "undefined" ? window : globalThis);
